final_build.solution:
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { readFileSync } from "node:fs";

type Todo = {
  id: number;
  title: string;
  done: boolean;
};

const todos: Todo[] = [];
let nextId = 1;

function addTodo(title: string): Todo {
  const todo: Todo = { id: nextId, title: title, done: false };
  nextId = nextId + 1;
  todos.push(todo);
  return todo;
}

function findTodo(id: number): Todo | undefined {
  return todos.find((t) => t.id === id);
}

function send(res: ServerResponse, status: number, data: object): void {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(data));
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise<string>((resolve) => {
    req.setEncoding("utf8");
    let body = "";
    req.on("data", (chunk: string) => {
      body = body + chunk;
    });
    req.on("end", () => {
      resolve(body);
    });
  });
}

function idText(pathname: string): string | undefined {
  const parts = pathname.split("/");
  if (parts.length !== 3 || parts[1] !== "todos") {
    return undefined;
  }
  return parts[2];
}

function parseId(text: string): number | undefined {
  const id = Number(text);
  if (!Number.isInteger(id) || id < 1) {
    return undefined;
  }
  return id;
}

function todoId(pathname: string): number | undefined {
  const text = idText(pathname);
  if (text === undefined) {
    return undefined;
  }
  return parseId(text);
}

function updateTodo(todo: Todo, changes: Partial<Todo>): Todo {
  const updated: Todo = { ...todo, ...changes };
  const i = todos.indexOf(todo);
  todos[i] = updated;
  return updated;
}

function deleteTodo(id: number): boolean {
  const i = todos.findIndex((t) => t.id === id);
  if (i === -1) {
    return false;
  }
  todos.splice(i, 1);
  return true;
}

function sendEmpty(res: ServerResponse, status: number): void {
  res.writeHead(status);
  res.end();
}

function objectFrom(data: unknown): object | undefined {
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    return undefined;
  }
  return data;
}

function titleFrom(data: unknown): string | undefined {
  const obj = objectFrom(data);
  if (obj === undefined || !("title" in obj) || typeof obj.title !== "string") {
    return undefined;
  }
  return obj.title;
}

function changesFrom(data: unknown): Partial<Todo> | undefined {
  const obj = objectFrom(data);
  if (obj === undefined) {
    return undefined;
  }
  const changes: Partial<Todo> = {};
  if ("title" in obj) {
    if (typeof obj.title !== "string") {
      return undefined;
    }
    changes.title = obj.title;
  }
  if ("done" in obj) {
    if (typeof obj.done !== "boolean") {
      return undefined;
    }
    changes.done = obj.done;
  }
  return changes;
}

async function handler(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? "/", "http://localhost");
  const id = todoId(url.pathname);

  if (req.method === "GET" && url.pathname === "/todos") {
    send(res, 200, todos);
    return;
  }

  if (req.method === "POST" && url.pathname === "/todos") {
    const body = await readBody(req);
    const data: unknown = JSON.parse(body);
    const title = titleFrom(data);
    if (title === undefined) {
      send(res, 400, { error: "invalid_body" });
      return;
    }
    const todo = addTodo(title);
    send(res, 201, todo);
    return;
  }

  if (req.method === "GET" && id !== undefined) {
    const todo = findTodo(id);
    if (todo === undefined) {
      send(res, 404, { error: "not_found" });
      return;
    }
    send(res, 200, todo);
    return;
  }

  if (req.method === "PATCH" && id !== undefined) {
    const todo = findTodo(id);
    if (todo === undefined) {
      send(res, 404, { error: "not_found" });
      return;
    }
    const body = await readBody(req);
    const data: unknown = JSON.parse(body);
    const changes = changesFrom(data);
    if (changes === undefined) {
      send(res, 400, { error: "invalid_body" });
      return;
    }
    const updated = updateTodo(todo, changes);
    send(res, 200, updated);
    return;
  }

  if (req.method === "DELETE" && id !== undefined) {
    const removed = deleteTodo(id);
    if (!removed) {
      send(res, 404, { error: "not_found" });
      return;
    }
    sendEmpty(res, 204);
    return;
  }

  send(res, 404, { error: "not_found" });
}

// ---- request replayer (given — don't edit) --------------------------------
// stdin:  one request per line —  METHOD /path [json body]
// stdout: one line per request —  <status> <response body>
// An error your handler throws becomes a 500 — exactly what a framework does.
const server = createServer((req, res) => {
  Promise.resolve(handler(req, res)).catch((err: unknown) => {
    console.error(err);
    if (res.headersSent) { res.end(); return; }
    res.writeHead(500, { "Content-Type": "application/json" });
    res.end('{"error":"server_error"}');
  });
});
await new Promise<void>((ok) => server.listen(0, "127.0.0.1", () => ok()));
const addr = server.address();
const base = `http://127.0.0.1:${addr === null ? 0 : addr.port}`;
for (const line of readFileSync(0, "utf8").split("\n")) {
  const text = line.trim();
  if (!text) continue;
  const parts = text.split(" ");
  const method = parts[0] ?? "GET";
  const path = parts[1] ?? "/";
  const body = parts.slice(2).join(" ");
  const headers: Record<string, string> = {};
  if (body) headers["Content-Type"] = "application/json";
  const reply = await fetch(base + path, { method, headers, body: body || undefined });
  console.log(reply.status, (await reply.text()).trim());
}
server.close();

